import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"SDK source branches","description":"Languages live on sdk/<lang> orphan branches. Go/PHP/Swift sources are *-src plus dedicated repos.","frontmatter":{"title":"SDK source branches","description":"Languages live on sdk/<lang> orphan branches. Go/PHP/Swift sources are *-src plus dedicated repos."},"headers":[],"relativePath":"en/contribute/sdk.md","filePath":"en/contribute/sdk.md","lastUpdated":1790057721000}`),a={name:`en/contribute/sdk.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="sdk-source-branches" tabindex="-1">SDK source branches <a class="header-anchor" href="#sdk-source-branches" aria-label="Permalink to “SDK source branches”">​</a></h1><p>Each language is an orphan branch <code>sdk/&lt;lang&gt;</code>. Go/PHP/Swift full sources are <code>sdk/go-src</code>, <code>sdk/php-src</code>, <code>sdk/swift-src</code>; <code>sdk/go</code> and siblings are pointer READMEs. Do not draw language package roots on the default-branch tree.</p><p>Publish coordinates, dedicated-repo steps, and the GitHub Actions auto-release (Conventional Commits, <code>sdk-&lt;lang&gt;-v*</code> tags, secret names) live in <code>docs/sdk-publish.md</code>. User install docs: <a href="/en/api/sdk/">API → SDK</a>. Do not put maintainer <code>twine</code> / <code>cargo publish</code> or CI secrets on user SDK pages.</p><h2 id="only-a-merged-pull-request-publishes" tabindex="-1">Only a merged pull request publishes <a class="header-anchor" href="#only-a-merged-pull-request-publishes" aria-label="Permalink to “Only a merged pull request publishes”">​</a></h2><ul><li>Each pipelined <code>sdk/&lt;lang&gt;</code> branch publishes <strong>only</strong> when a pull request targeting that branch is merged (<code>pull_request: types: [closed]</code> + <code>merged == true</code>). Direct pushes, and closed-but-unmerged pull requests, stay silent.</li><li>Merging into <code>main</code> never publishes an SDK; the server release is a separate manual <code>workflow_dispatch</code>, see <a href="/en/contribute/release">Release and Docker</a>.</li><li><code>sdk/c</code> and <code>sdk/cpp</code> have their own pipelines but ship <strong>no registry package</strong>: the release attaches a source archive zip (<code>kirivers-&lt;lang&gt;-&lt;semver&gt;.zip</code>) to the GitHub Release.</li><li>The pointer branches <code>sdk/go</code>, <code>sdk/php</code>, <code>sdk/swift</code> have <strong>no</strong> workflows; the <code>sdk/*-src</code> pipelines only run tests inside this repository (the plan <code>skip</code>s when the repository identity is not the publish remote), and the real tag / publish happens in the copied-out dedicated repo — see <code>docs/sdk-publish.md</code>.</li><li>The changelog is written back to each branch&#39;s own <code>CHANGELOG.md</code> (created if missing); do not hand-edit it.</li></ul>`,5)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};